workspace "Order Management Platform" "Customer-facing web store with order processing and inventory integration" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "A customer who browses the web store and places orders"
        support = person "Support Agent" "A support agent who manages orders and handles customer inquiries"

        store = softwareSystem "Web Store" "The customer-facing web store where orders are placed and managed" {
            web = container "Web Application" "Serves the storefront and order entry UI" "React" "Web"
            api = container "Order API" "REST API for order management" "Node.js" "Service"
            db = container "Order Database" "Stores orders and customer data" "PostgreSQL" "Database"
        }

        inventory = softwareSystem "Inventory System" "External system that tracks stock levels" "External"

        customer -> store.web "places orders through" "HTTPS"
        support -> store.api "manages orders via" "HTTPS"
        store.web -> store.api "submits order requests to" "HTTPS"
        store.api -> store.db "persists orders in" "SQL"
        store.api -> inventory "checks stock levels with" "HTTPS"
    }

    views {
        systemLandscape "Landscape" {
            include *
            autoLayout
            title "System Landscape"
        }

        systemContext store "StoreContext" {
            include *
            autoLayout
            title "System Context for Web Store"
        }

        container store "StoreContainers" {
            include *
            autoLayout
            title "Containers for Web Store"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }
}

